308	    unsafe fn create_menu_item(
309	        item: &MenuItem,
310	        delegate: id,
311	        actions: &mut Vec<Box<dyn Action>>,
312	        keymap: &Keymap,
313	    ) -> id {
314	        static DEFAULT_CONTEXT: OnceLock<Vec<KeyContext>> = OnceLock::new();
315	
316	        unsafe {
317	            match item {
318	                MenuItem::Separator => NSMenuItem::separatorItem(nil),
319	                MenuItem::Action {
320	                    name,
321	                    action,
322	                    os_action,
323	                    checked,
324	                    disabled,
325	                } => {
326	                    // Note that this is intentionally using earlier bindings, whereas typically
327	                    // later ones take display precedence. See the discussion on
328	                    // https://github.com/zed-industries/zed/issues/23621
329	                    let keystrokes = keymap
330	                        .bindings_for_action(action.as_ref())
331	                        .find_or_first(|binding| {
332	                            binding.predicate().is_none_or(|predicate| {
333	                                predicate.eval(DEFAULT_CONTEXT.get_or_init(|| {
334	                                    let mut workspace_context = KeyContext::new_with_defaults();
335	                                    workspace_context.add("Workspace");
336	                                    let mut pane_context = KeyContext::new_with_defaults();
337	                                    pane_context.add("Pane");
338	                                    let mut editor_context = KeyContext::new_with_defaults();
339	                                    editor_context.add("Editor");
340	
341	                                    pane_context.extend(&editor_context);
342	                                    workspace_context.extend(&pane_context);
343	                                    vec![workspace_context]
344	                                }))
345	                            })
346	                        })
347	                        .map(|binding| binding.keystrokes());
348	
349	                    let selector = match os_action {
350	                        Some(gpui::OsAction::Cut) => selector("cut:"),
351	                        Some(gpui::OsAction::Copy) => selector("copy:"),
352	                        Some(gpui::OsAction::Paste) => selector("paste:"),
353	                        Some(gpui::OsAction::SelectAll) => selector("selectAll:"),
354	                        // "undo:" and "redo:" are always disabled in our case, as
355	                        // we don't have a NSTextView/NSTextField to enable them on.
356	                        Some(gpui::OsAction::Undo) => selector("handleGPUIMenuItem:"),
357	                        Some(gpui::OsAction::Redo) => selector("handleGPUIMenuItem:"),
358	                        None => selector("handleGPUIMenuItem:"),
359	                    };
360	
361	                    let item;
362	                    if let Some(keystrokes) = keystrokes {
363	                        if keystrokes.len() == 1 {
364	                            let keystroke = &keystrokes[0];
365	                            let mut mask = NSEventModifierFlags::empty();
366	                            for (modifier, flag) in &[
367	                                (
368	                                    keystroke.modifiers().platform,
369	                                    NSEventModifierFlags::NSCommandKeyMask,
370	                                ),
371	                                (
372	                                    keystroke.modifiers().control,
373	                                    NSEventModifierFlags::NSControlKeyMask,
374	                                ),
375	                                (
376	                                    keystroke.modifiers().alt,
377	                                    NSEventModifierFlags::NSAlternateKeyMask,
378	                                ),
379	                                (
380	                                    keystroke.modifiers().shift,
381	                                    NSEventModifierFlags::NSShiftKeyMask,
382	                                ),
383	                            ] {
384	                                if *modifier {
385	                                    mask |= *flag;
386	                                }
387	                            }
388	
389	                            item = NSMenuItem::alloc(nil)
390	                                .initWithTitle_action_keyEquivalent_(
391	                                    ns_string(name),
392	                                    selector,
393	                                    ns_string(key_to_native(keystroke.key()).as_ref()),
394	                                )
395	                                .autorelease();
396	                            if Self::os_version() >= Version::new(12, 0, 0) {
397	                                let _: () = msg_send![item, setAllowsAutomaticKeyEquivalentLocalization: NO];
398	                            }
399	                            item.setKeyEquivalentModifierMask_(mask);
400	                        } else {
401	                            item = NSMenuItem::alloc(nil)
402	                                .initWithTitle_action_keyEquivalent_(
403	                                    ns_string(name),
404	                                    selector,
405	                                    ns_string(""),
406	                                )
407	                                .autorelease();
408	                        }
409	                    } else {
410	                        item = NSMenuItem::alloc(nil)
411	                            .initWithTitle_action_keyEquivalent_(
412	                                ns_string(name),
413	                                selector,
414	                                ns_string(""),
415	                            )
416	                            .autorelease();
417	                    }
418	
419	                    if *checked {
420	                        item.setState_(NSVisualEffectState::Active);
421	                    }
422	                    item.setEnabled_(if *disabled { NO } else { YES });
423	
424	                    let tag = actions.len() as NSInteger;
425	                    let _: () = msg_send![item, setTag: tag];
426	                    actions.push(action.boxed_clone());
427	                    item
428	                }
429	                MenuItem::Submenu(Menu {
430	                    name,
431	                    items,
432	                    disabled,
433	                }) => {
434	                    let item = NSMenuItem::new(nil).autorelease();
435	                    let submenu = NSMenu::new(nil).autorelease();
436	                    submenu.setDelegate_(delegate);
437	                    for item in items {
438	                        submenu.addItem_(Self::create_menu_item(item, delegate, actions, keymap));
439	                    }
440	                    item.setSubmenu_(submenu);
441	                    item.setEnabled_(if *disabled { NO } else { YES });
442	                    item.setTitle_(ns_string(name));
443	                    item
444	                }
445	                MenuItem::SystemMenu(OsMenu { name, menu_type }) => {
446	                    let item = NSMenuItem::new(nil).autorelease();
447	                    let submenu = NSMenu::new(nil).autorelease();
448	                    submenu.setDelegate_(delegate);
449	                    item.setSubmenu_(submenu);
450	                    item.setTitle_(ns_string(name));
451	
452	                    match menu_type {
453	                        SystemMenuType::Services => {
454	                            let app: id = msg_send![APP_CLASS, sharedApplication];
455	                            app.setServicesMenu_(item);
456	                        }
457	                    }
458	
459	                    item
460	                }
461	            }
462	        }
463	    }
