491	    fn run(&self, on_finish_launching: Box<dyn FnOnce()>) {
492	        let mut state = self.0.lock();
493	        if state.headless {
494	            drop(state);
495	            on_finish_launching();
496	            unsafe { CFRunLoopRun() };
497	        } else {
498	            state.finish_launching = Some(on_finish_launching);
499	            drop(state);
500	        }
501	
502	        unsafe {
503	            let app: id = msg_send![APP_CLASS, sharedApplication];
504	            let app_delegate: id = msg_send![APP_DELEGATE_CLASS, new];
505	            app.setDelegate_(app_delegate);
506	
507	            let self_ptr = self as *const Self as *const c_void;
508	            (*app).set_ivar(MAC_PLATFORM_IVAR, self_ptr);
509	            (*app_delegate).set_ivar(MAC_PLATFORM_IVAR, self_ptr);
510	
511	            let pool = NSAutoreleasePool::new(nil);
512	            app.run();
513	            pool.drain();
514	
515	            (*app).set_ivar(MAC_PLATFORM_IVAR, null_mut::<c_void>());
516	            (*NSWindow::delegate(app)).set_ivar(MAC_PLATFORM_IVAR, null_mut::<c_void>());
517	        }
518	    }
