520	    fn quit(&self) {
521	        // Quitting the app causes us to close windows, which invokes `Window::on_close` callbacks
522	        // synchronously before this method terminates. If we call `Platform::quit` while holding a
523	        // borrow of the app state (which most of the time we will do), we will end up
524	        // double-borrowing the app state in the `on_close` callbacks for our open windows. To solve
525	        // this, we make quitting the application asynchronous so that we aren't holding borrows to
526	        // the app state on the stack when we actually terminate the app.
527	
528	        unsafe {
529	            DispatchQueue::main().exec_async_f(ptr::null_mut(), quit);
530	        }
531	
532	        extern "C" fn quit(_: *mut c_void) {
533	            unsafe {
534	                let app = NSApplication::sharedApplication(nil);
535	                let _: () = msg_send![app, terminate: nil];
536	            }
537	        }
538	    }
