540	    fn restart(&self, binary_path: Option<PathBuf>, arguments: Vec<std::ffi::OsString>) {
541	        use std::os::unix::process::CommandExt as _;
542	
543	        let app_pid = std::process::id().to_string();
544	        let app_path = binary_path
545	            .or_else(|| {
546	                self.app_path()
547	                    .ok()
548	                    // When the app is not bundled, `app_path` returns the
549	                    // directory containing the executable. Disregard this
550	                    // and get the path to the executable itself.
551	                    .and_then(|path| (path.extension()?.to_str()? == "app").then_some(path))
552	            })
553	            .unwrap_or_else(|| std::env::current_exe().unwrap());
554	
555	        // Wait until this process has exited and then re-open this path.
556	        let script = r#"
557	            while kill -0 $0 2> /dev/null; do
558	                sleep 0.1
559	            done
560	            app_path="$1"
561	            shift
562	            if (($# > 0)); then
563	                open "$app_path" --args "$@"
564	            else
565	                open "$app_path"
566	            fi
567	        "#;
568	
569	        #[allow(
570	            clippy::disallowed_methods,
571	            reason = "We are restarting ourselves, using std command thus is fine"
572	        )]
573	        let restart_process = new_std_command("/bin/bash")
574	            .arg("-c")
575	            .arg(script)
576	            .arg(app_pid)
577	            .arg(app_path)
578	            .args(arguments)
579	            .process_group(0)
580	            .spawn();
581	
582	        match restart_process {
583	            Ok(_) => self.quit(),
584	            Err(e) => log::error!("failed to spawn restart script: {:?}", e),
585	        }
586	    }
