724	    fn register_url_scheme(&self, scheme: &str) -> Task<anyhow::Result<()>> {
725	        // API only available post Monterey
726	        // https://developer.apple.com/documentation/appkit/nsworkspace/3753004-setdefaultapplicationaturl
727	        let (done_tx, done_rx) = oneshot::channel();
728	        if Self::os_version() < Version::new(12, 0, 0) {
729	            return Task::ready(Err(anyhow!(
730	                "macOS 12.0 or later is required to register URL schemes"
731	            )));
732	        }
733	
734	        let bundle_id = unsafe {
735	            let bundle: id = msg_send![class!(NSBundle), mainBundle];
736	            let bundle_id: id = msg_send![bundle, bundleIdentifier];
737	            if bundle_id == nil {
738	                return Task::ready(Err(anyhow!("Can only register URL scheme in bundled apps")));
739	            }
740	            bundle_id
741	        };
742	
743	        unsafe {
744	            let workspace: id = msg_send![class!(NSWorkspace), sharedWorkspace];
745	            let scheme: id = ns_string(scheme);
746	            let app: id = msg_send![workspace, URLForApplicationWithBundleIdentifier: bundle_id];
747	            if app == nil {
748	                return Task::ready(Err(anyhow!(
749	                    "Cannot register URL scheme until app is installed"
750	                )));
751	            }
752	            let done_tx = Cell::new(Some(done_tx));
753	            let block = ConcreteBlock::new(move |error: id| {
754	                let result = if error == nil {
755	                    Ok(())
756	                } else {
757	                    let msg: id = msg_send![error, localizedDescription];
758	                    Err(anyhow!("Failed to register: {msg:?}"))
759	                };
760	
761	                if let Some(done_tx) = done_tx.take() {
762	                    let _ = done_tx.send(result);
763	                }
764	            });
765	            let block = block.copy();
766	            let _: () = msg_send![workspace, setDefaultApplicationAtURL: app toOpenURLsWithScheme: scheme completionHandler: block];
767	        }
768	
769	        self.background_executor()
770	            .spawn(async { done_rx.await.map_err(|e| anyhow!(e))? })
771	    }
