792	                    let done_tx = Cell::new(Some(done_tx));
793	                    let block = ConcreteBlock::new(move |response: NSModalResponse| {
794	                        let result = if response == NSModalResponse::NSModalResponseOk {
795	                            let mut result = Vec::new();
796	                            let urls = panel.URLs();
797	                            for i in 0..urls.count() {
798	                                let url = urls.objectAtIndex(i);
799	                                if url.isFileURL() == YES
800	                                    && let Ok(path) = ns_url_to_path(url)
801	                                {
802	                                    result.push(path)
