804	                            }
805	                            Some(result)
806	                        } else {
807	                            None
808	                        };
809	
810	                        if let Some(done_tx) = done_tx.take() {
811	                            let _ = done_tx.send(Ok(result));
812	                        }
813	                    });
814	                    let block = block.copy();
815	
816	                    if let Some(prompt) = options.prompt {
817	                        let _: () = msg_send![panel, setPrompt: ns_string(&prompt)];
818	                    }
819	
820	                    let _: () = msg_send![panel, beginWithCompletionHandler: block];
