827	    fn prompt_for_new_path(
828	        &self,
829	        directory: &Path,
830	        suggested_name: Option<&str>,
831	    ) -> oneshot::Receiver<Result<Option<PathBuf>>> {
832	        let directory = directory.to_owned();
833	        let suggested_name = suggested_name.map(|s| s.to_owned());
834	        let (done_tx, done_rx) = oneshot::channel();
835	        self.foreground_executor()
836	            .spawn(async move {
837	                unsafe {
838	                    let panel = NSSavePanel::savePanel(nil);
839	                    let path = ns_string(directory.to_string_lossy().as_ref());
840	                    let url = NSURL::fileURLWithPath_isDirectory_(nil, path, true.to_objc());
841	                    panel.setDirectoryURL(url);
842	
843	                    if let Some(suggested_name) = suggested_name {
844	                        let name_string = ns_string(&suggested_name);
845	                        let _: () = msg_send![panel, setNameFieldStringValue: name_string];
846	                    }
847	
848	                    let done_tx = Cell::new(Some(done_tx));
849	                    let block = ConcreteBlock::new(move |response: NSModalResponse| {
850	                        let mut result = None;
851	                        if response == NSModalResponse::NSModalResponseOk {
852	                            let url = panel.URL();
853	                            if url.isFileURL() == YES {
854	                                result = ns_url_to_path(panel.URL()).ok().map(|mut result| {
855	                                    let Some(filename) = result.file_name() else {
856	                                        return result;
857	                                    };
858	                                    let chunks = filename
859	                                        .as_bytes()
860	                                        .split(|&b| b == b'.')
861	                                        .collect::<Vec<_>>();
862	
863	                                    // https://github.com/zed-industries/zed/issues/16969
864	                                    // Workaround a bug in macOS Sequoia that adds an extra file-extension
865	                                    // sometimes. e.g. `a.sql` becomes `a.sql.s` or `a.txtx` becomes `a.txtx.txt`
866	                                    //
867	                                    // This is conditional on OS version because I'd like to get rid of it, so that
868	                                    // you can manually create a file called `a.sql.s`. That said it seems better
869	                                    // to break that use-case than breaking `a.sql`.
870	                                    if chunks.len() == 3
871	                                        && chunks[1].starts_with(chunks[2])
872	                                        && Self::os_version() >= Version::new(15, 0, 0)
873	                                    {
874	                                        let new_filename = OsStr::from_bytes(
875	                                            &filename.as_bytes()
876	                                                [..chunks[0].len() + 1 + chunks[1].len()],
877	                                        )
878	                                        .to_owned();
879	                                        result.set_file_name(&new_filename);
880	                                    }
881	                                    result
882	                                })
883	                            }
