1143	    fn write_credentials(&self, url: &str, username: &str, password: &[u8]) -> Task<Result<()>> {
1144	        let url = url.to_string();
1145	        let username = username.to_string();
1146	        let password = password.to_vec();
1147	        self.background_executor().spawn(async move {
1148	            unsafe {
1149	                use security::*;
1150	
1151	                let url = CFString::from(url.as_str());
1152	                let username = CFString::from(username.as_str());
1153	                let password = CFData::from_buffer(&password);
1154	
1155	                // First, check if there are already credentials for the given server. If so, then
1156	                // update the username and password.
1157	                let mut verb = "updating";
1158	                let mut query_attrs = CFMutableDictionary::with_capacity(2);
1159	                query_attrs.set(kSecClass as *const _, kSecClassInternetPassword as *const _);
1160	                query_attrs.set(kSecAttrServer as *const _, url.as_CFTypeRef());
1161	
1162	                let mut attrs = CFMutableDictionary::with_capacity(4);
1163	                attrs.set(kSecClass as *const _, kSecClassInternetPassword as *const _);
1164	                attrs.set(kSecAttrServer as *const _, url.as_CFTypeRef());
1165	                attrs.set(kSecAttrAccount as *const _, username.as_CFTypeRef());
1166	                attrs.set(kSecValueData as *const _, password.as_CFTypeRef());
1167	
1168	                let mut status = SecItemUpdate(
1169	                    query_attrs.as_concrete_TypeRef(),
1170	                    attrs.as_concrete_TypeRef(),
1171	                );
1172	
1173	                // If there were no existing credentials for the given server, then create them.
1174	                if status == errSecItemNotFound {
1175	                    verb = "creating";
1176	                    status = SecItemAdd(attrs.as_concrete_TypeRef(), ptr::null_mut());
1177	                }
1178	                anyhow::ensure!(status == errSecSuccess, "{verb} password failed: {status}");
1179	            }
1180	            Ok(())
1181	        })
1182	    }
