1184	    fn read_credentials(&self, url: &str) -> Task<Result<Option<(String, Vec<u8>)>>> {
1185	        let url = url.to_string();
1186	        self.background_executor().spawn(async move {
1187	            let url = CFString::from(url.as_str());
1188	            let cf_true = CFBoolean::true_value().as_CFTypeRef();
1189	
1190	            unsafe {
1191	                use security::*;
1192	
1193	                // Find any credentials for the given server URL.
1194	                let mut attrs = CFMutableDictionary::with_capacity(5);
1195	                attrs.set(kSecClass as *const _, kSecClassInternetPassword as *const _);
1196	                attrs.set(kSecAttrServer as *const _, url.as_CFTypeRef());
1197	                attrs.set(kSecReturnAttributes as *const _, cf_true);
1198	                attrs.set(kSecReturnData as *const _, cf_true);
1199	
1200	                let mut result = CFTypeRef::from(ptr::null());
1201	                let status = SecItemCopyMatching(attrs.as_concrete_TypeRef(), &mut result);
1202	                match status {
1203	                    security::errSecSuccess => {}
1204	                    security::errSecItemNotFound | security::errSecUserCanceled => return Ok(None),
1205	                    _ => anyhow::bail!("reading password failed: {status}"),
1206	                }
1207	
1208	                let result = CFType::wrap_under_create_rule(result)
1209	                    .downcast::<CFDictionary>()
1210	                    .context("keychain item was not a dictionary")?;
1211	                let username = result
1212	                    .find(kSecAttrAccount as *const _)
1213	                    .context("account was missing from keychain item")?;
1214	                let username = CFType::wrap_under_get_rule(*username)
1215	                    .downcast::<CFString>()
1216	                    .context("account was not a string")?;
1217	                let password = result
1218	                    .find(kSecValueData as *const _)
1219	                    .context("password was missing from keychain item")?;
1220	                let password = CFType::wrap_under_get_rule(*password)
1221	                    .downcast::<CFData>()
1222	                    .context("password was not a string")?;
1223	
1224	                Ok(Some((username.to_string(), password.bytes().to_vec())))
1225	            }
1226	        })
1227	    }
