        drop(state);

        // SAFETY: APP_CLASS is registered during startup and returns the shared NSApplication.
        unsafe {
            let app: id = msg_send![APP_CLASS, sharedApplication];
            let delegate: id = msg_send![app, delegate];
            if delegate != nil {
