127	                            .contains(NSEventModifierFlags::NSAlphaShiftKeyMask),
128	                    },
129	                }))
130	            }
131	            NSEventType::NSKeyDown => Some(PlatformInput::KeyDown(KeyDownEvent {
132	                keystroke: parse_keystroke(native_event),
