458	                if !control && !command && !function {
459	                    let mut mods = NO_MOD;
460	                    if shift {
461	                        mods |= SHIFT_MOD;
462	                    }
463	                    if alt {
464	                        mods |= OPTION_MOD;
465	                    }
466	
